create table public.teacher_lesson_plans (id uuid primary key default gen_random_uuid(),school_id uuid not null references public.schools(id) on delete cascade,class_id uuid not null references public.classes(id) on delete cascade,subject_id uuid not null references public.subjects(id) on delete cascade,term_id uuid not null references public.terms(id) on delete cascade,teacher_membership_id uuid not null references public.school_memberships(id) on delete cascade,lesson_date date not null,topic text not null check(length(trim(topic)) between 2 and 180),learning_objectives text not null default '',lesson_activities text not null default '',resources text not null default '',homework_notes text not null default '',status text not null default 'planned' check(status in('planned','completed')),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),foreign key(school_id,class_id) references public.classes(school_id,id));
create table public.teacher_homework_tasks (id uuid primary key default gen_random_uuid(),school_id uuid not null references public.schools(id) on delete cascade,class_id uuid not null references public.classes(id) on delete cascade,subject_id uuid not null references public.subjects(id) on delete cascade,term_id uuid not null references public.terms(id) on delete cascade,teacher_membership_id uuid not null references public.school_memberships(id) on delete cascade,title text not null check(length(trim(title)) between 2 and 180),instructions text not null default '',assigned_date date not null default current_date,due_date date not null,max_score numeric(7,2) check(max_score is null or max_score>0),status text not null default 'assigned' check(status in('assigned','closed')),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),foreign key(school_id,class_id) references public.classes(school_id,id),check(due_date>=assigned_date));
create table public.teacher_homework_submissions (id uuid primary key default gen_random_uuid(),school_id uuid not null references public.schools(id) on delete cascade,task_id uuid not null references public.teacher_homework_tasks(id) on delete cascade,student_id uuid not null references public.students(id) on delete cascade,submitted_at timestamptz,response_text text not null default '',score numeric(7,2),teacher_feedback text not null default '',status text not null default 'not_submitted' check(status in('not_submitted','submitted','graded','late')),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(task_id,student_id));
create index teacher_lesson_plans_teacher_date_idx on public.teacher_lesson_plans(teacher_membership_id,lesson_date desc);create index teacher_homework_tasks_teacher_due_idx on public.teacher_homework_tasks(teacher_membership_id,due_date);
alter table public.teacher_lesson_plans enable row level security;alter table public.teacher_homework_tasks enable row level security;alter table public.teacher_homework_submissions enable row level security;
grant select,insert,update,delete on public.teacher_lesson_plans to authenticated;grant select,insert,update,delete on public.teacher_homework_tasks to authenticated;grant select on public.teacher_homework_submissions to authenticated;
create policy lesson_plan_read on public.teacher_lesson_plans for select to authenticated using(exists(select 1 from public.school_memberships m where m.id=teacher_lesson_plans.teacher_membership_id and m.user_id=(select auth.uid()) and m.school_id=teacher_lesson_plans.school_id and m.is_active) or exists(select 1 from public.school_memberships m where m.user_id=(select auth.uid()) and m.school_id=teacher_lesson_plans.school_id and m.is_active and m.role in('owner','proprietor','school_admin','headteacher','deputy_headteacher','academic_officer')));
create policy lesson_plan_insert on public.teacher_lesson_plans for insert to authenticated with check(exists(select 1 from public.school_memberships m where m.id=teacher_lesson_plans.teacher_membership_id and m.user_id=(select auth.uid()) and m.school_id=teacher_lesson_plans.school_id and m.is_active and m.role in('teacher','class_teacher')) and exists(select 1 from public.class_subjects cs where cs.school_id=teacher_lesson_plans.school_id and cs.class_id=teacher_lesson_plans.class_id and cs.subject_id=teacher_lesson_plans.subject_id and cs.teacher_membership_id=teacher_lesson_plans.teacher_membership_id) and exists(select 1 from public.terms t join public.classes c on c.id=teacher_lesson_plans.class_id and c.school_id=teacher_lesson_plans.school_id where t.id=teacher_lesson_plans.term_id and t.school_id=teacher_lesson_plans.school_id and t.academic_year_id=c.academic_year_id and teacher_lesson_plans.lesson_date between t.start_date and t.end_date));
create policy lesson_plan_update on public.teacher_lesson_plans for update to authenticated using(exists(select 1 from public.school_memberships m where m.id=teacher_lesson_plans.teacher_membership_id and m.user_id=(select auth.uid()) and m.school_id=teacher_lesson_plans.school_id and m.is_active)) with check(exists(select 1 from public.school_memberships m where m.id=teacher_lesson_plans.teacher_membership_id and m.user_id=(select auth.uid()) and m.school_id=teacher_lesson_plans.school_id and m.is_active) and exists(select 1 from public.class_subjects cs where cs.school_id=teacher_lesson_plans.school_id and cs.class_id=teacher_lesson_plans.class_id and cs.subject_id=teacher_lesson_plans.subject_id and cs.teacher_membership_id=teacher_lesson_plans.teacher_membership_id));
create policy lesson_plan_delete on public.teacher_lesson_plans for delete to authenticated using(exists(select 1 from public.school_memberships m where m.id=teacher_lesson_plans.teacher_membership_id and m.user_id=(select auth.uid()) and m.school_id=teacher_lesson_plans.school_id and m.is_active));
create policy homework_read on public.teacher_homework_tasks for select to authenticated using(exists(select 1 from public.school_memberships m where m.id=teacher_homework_tasks.teacher_membership_id and m.user_id=(select auth.uid()) and m.school_id=teacher_homework_tasks.school_id and m.is_active) or exists(select 1 from public.school_memberships m where m.user_id=(select auth.uid()) and m.school_id=teacher_homework_tasks.school_id and m.is_active and m.role in('owner','proprietor','school_admin','headteacher','deputy_headteacher','academic_officer')));
create policy homework_insert on public.teacher_homework_tasks for insert to authenticated with check(exists(select 1 from public.school_memberships m where m.id=teacher_homework_tasks.teacher_membership_id and m.user_id=(select auth.uid()) and m.school_id=teacher_homework_tasks.school_id and m.is_active and m.role in('teacher','class_teacher')) and exists(select 1 from public.class_subjects cs where cs.school_id=teacher_homework_tasks.school_id and cs.class_id=teacher_homework_tasks.class_id and cs.subject_id=teacher_homework_tasks.subject_id and cs.teacher_membership_id=teacher_homework_tasks.teacher_membership_id) and exists(select 1 from public.terms t join public.classes c on c.id=teacher_homework_tasks.class_id and c.school_id=teacher_homework_tasks.school_id where t.id=teacher_homework_tasks.term_id and t.school_id=teacher_homework_tasks.school_id and t.academic_year_id=c.academic_year_id and teacher_homework_tasks.assigned_date between t.start_date and t.end_date and teacher_homework_tasks.due_date between t.start_date and t.end_date));
create policy homework_update on public.teacher_homework_tasks for update to authenticated using(exists(select 1 from public.school_memberships m where m.id=teacher_homework_tasks.teacher_membership_id and m.user_id=(select auth.uid()) and m.school_id=teacher_homework_tasks.school_id and m.is_active)) with check(exists(select 1 from public.school_memberships m where m.id=teacher_homework_tasks.teacher_membership_id and m.user_id=(select auth.uid()) and m.school_id=teacher_homework_tasks.school_id and m.is_active) and exists(select 1 from public.class_subjects cs where cs.school_id=teacher_homework_tasks.school_id and cs.class_id=teacher_homework_tasks.class_id and cs.subject_id=teacher_homework_tasks.subject_id and cs.teacher_membership_id=teacher_homework_tasks.teacher_membership_id));
create policy homework_delete on public.teacher_homework_tasks for delete to authenticated using(exists(select 1 from public.school_memberships m where m.id=teacher_homework_tasks.teacher_membership_id and m.user_id=(select auth.uid()) and m.school_id=teacher_homework_tasks.school_id and m.is_active));
create policy homework_submission_read on public.teacher_homework_submissions for select to authenticated using(exists(select 1 from public.teacher_homework_tasks h join public.school_memberships m on m.id=h.teacher_membership_id where h.id=teacher_homework_submissions.task_id and h.school_id=teacher_homework_submissions.school_id and m.user_id=(select auth.uid()) and m.is_active) or exists(select 1 from public.school_memberships m where m.user_id=(select auth.uid()) and m.school_id=teacher_homework_submissions.school_id and m.is_active and m.role in('owner','proprietor','school_admin','headteacher','deputy_headteacher','academic_officer')));